Actor = class("Actor")

function Actor:ctor(id)
    --this.rigidBody = nil;
    self.id = id;
    self.health = 100;
    self.onDead = nil;
    self.onHurted = nil;
end

function Actor:Init(gameObject)
    --TODO: 获得刚体。gameObject
    self.gameObject = gameObject;
end

function Actor:Reset()
    self.health = 100;
end

---
--- 攻击。
--- 产生一个攻击向量。方向和力量都在一定范围随机。
---
function Actor:Attack(target)
    --TODO: 生成一个随机的方向向量。
    --TODO: 生成一个随机的力量。
    --this.rigidBody.AddForce();
    local position = self.gameObject.transform.localPosition;
    local offset = UnityEngine.Random.Range(20, 50);
    if self.id == 1 then
        offset = offset;
    else
        offset = -offset;
    end
    self.gameObject.transform.localPosition = Vector3.New(position.x+offset, position.y, position.z);
    local distance = Vector3.Distance(self.gameObject.transform.localPosition, target.gameObject.transform.localPosition);
    Debug.Log("当前距离:"..distance);
    if distance < 160 then
        local hurtValue = UnityEngine.Random.Range(1, 10);
        target:Hurt(hurtValue);
    end
end

function Actor:Hurt(value)
    self.health = self.health - value;
    if self.health <= 0 then
        self:OnDead();
    else
        self:OnHurted(self.health);
    end
end

function Actor:OnDead()
    if self.onDead ~= nil then
        self.onDead(self.id);
    end
end

function Actor:OnHurted(value)
    if self.onHurted ~= nil then
        self.onHurted(self.id, value);
    end
end